"""Verified company information from data/company.json and the referenced pages."""
from pathlib import Path
from html import escape as e
from urllib.parse import urlencode,quote
import json

def build_company_pages(root,shell,pagehead,icon):
 c=json.loads((root/'data/company.json').read_text())
 def section(title,body):return f'<section class="company-section"><h2>{title}</h2>{body}</section>'
 def para(t):return f'<p>{t}</p>'
 def policy(name,title,sections):shell(name,title,pagehead(title,title,'Information for product enquiries, visits and orders.')+'<div class="section company-document">'+''.join(section(t,para(p)) for t,p in sections)+'</div>')
 roles=section('Two companies. Connected capabilities.', '<div class="company-two"><article><span class="eyebrow">PRODUCT BRAND</span><h3>Dr. Smith</h3><p>Smart Premium Products: premium quality, practical functionality and economical pricing. Dr. Smith manages its brand’s manufacturing, supply, installation and after-sales support, with an expanding in-house manufacturing range.</p></article><article><span class="eyebrow">PROCUREMENT & PROJECT COLLABORATOR</span><h3>Surgical Wholesale Mart Pvt. Ltd.</h3><p>A separate company supporting wider procurement, experience centres and hospital project coordination. Its manufacturing and multi-brand sourcing connect the Dr. Smith portfolio with broader hospital requirements.</p></article></div><p>The supplying entity and the responsibilities for each product or service are confirmed in the quotation or contract.</p>')
 timeline=section('A journey built on experience.', '<div class="company-facts"><article><strong>65+</strong><span>Years of family experience</span></article><article><strong>2015</strong><span>Build journey began</span></article><article><strong>2024</strong><span>Dr. Smith brand registration</span></article></div><p>The family journey began with surgical instruments and expanded across generations into hospital furniture and medical equipment.</p>')
 purpose=section('Mission, vision & values.', '<div class="company-two"><article><h3>Our mission</h3><p>Make premium healthcare products more accessible through practical functionality, thoughtful pricing and dependable customer support.</p></article><article><h3>Our vision</h3><p>Build a trusted healthcare product brand shaped by family experience, continuous improvement and the evolving needs of hospitals.</p></article></div><div class="company-tags">'+''.join(f'<span>{v}</span>' for v in ['Quality with purpose','Accessible premium value','Experience-led selection','Customer commitment','Accountability','Continuous improvement'])+'</div>')
 leaders=section('The Dr. Smith leadership team.', '<div class="leadership-grid">'+''.join(f'<article><span class="leader-monogram" aria-hidden="true">{"".join(n[0] for n in p["name"].split())}</span><h3>{e(p["name"])}</h3><strong>{e(p["role"])}</strong><p>{e(p["focus"])}.</p></article>' for p in c['leadership'])+'</div>')
 quality=section('Product quality & documentation.', '<p>Product selection considers healthcare needs, suitable materials, performance requirements and product support. The growing manufacturing range includes products made in India; confirm country of origin for each model.</p><p>Ask for applicable ISO, CE, FDA, GMP, CDSCO or MSME documentation for your selected product and legal supplying entity. Company registration and product conformity are distinct; coverage is confirmed per model or quotation.</p><a class="text-link" href="contact.html?subject=Product%20documentation">Request relevant documentation →</a>')
 who=section('Who we support.', '<div class="company-tags">'+''.join(f'<span>{v}</span>' for v in ['Government hospitals','Private hospitals','Nursing homes','Clinics','Medical colleges','Diagnostic centres','Institutional healthcare buyers'])+'</div><p>The portfolio spans hospital furniture, medical equipment, instruments, medical consumables, hospital linen and MGPS & modular OT products.</p>')
 figures=section('Published company figures.', '<div class="company-facts"><article><strong>100+</strong><span>Hospitals</span></article><article><strong>1,00,000+</strong><span>Products</span></article><article><strong>10,000+</strong><span>Satisfied customers</span></article></div><p class="form-note">Figures as published on the Dr. Smith company website; these are company-reported portfolio figures, not the count of products listed on this storefront.</p>')
 projects=section('Published project references.', '<p>The company catalogue records equipment supplied for a 500-bed hospital, 125 ventilators installed for The Art of Living Organisation, and export supply for Zimbabwe’s Ministry of Health & Family Care. These references concern equipment supply and installation.</p><p>Product planning for hospitals from 25 to 500 beds is discussed project by project. Architecture, civil, MEP, modular OT and MGPS coordination can involve partner-supported services through Surgical Wholesale Mart.</p><a class="text-link" href="contact.html?subject=Relevant%20project%20references">Request relevant project references →</a>')
 reach=section('Nationwide reach. International availability.', '<p>Manufacturing, office and experience-centre contacts are published across India and Sharjah, UAE. Confirm the destination, opening status and the products available for demonstration before visiting.</p><a class="button" href="locations.html">Explore all locations →</a>')
 shell('about.html','Company profile',pagehead('Company profile','Experience behind every product.','Meet the Dr. Smith product brand and Surgical Wholesale Mart, its procurement and project collaborator.')+'<div class="section company-document wide-document">'+roles+timeline+purpose+leaders+who+quality+figures+projects+reach+'</div>')
 locationcards=[]
 for l in c['locations']:
  directions='https://www.google.com/maps/search/?'+urlencode({'api':1,'query':l['address']})
  note=('Full visit address must be confirmed with the central team.' if not l['fullAddress'] else 'Confirm the address, opening status and demonstration availability before visiting.')
  if l['id']=='kapashera':note+=' The company address lists Plot No. 75/02; the map listing may show 76/02. Confirm the plot number with the team.'
  phones=''.join(f'<a href="tel:+{p["number"]}">{e(p["display"])}</a>' for p in l['additionalPhones'])
  locationcards.append(f'<article class="location-card" id="location-{l["id"]}"><span class="eyebrow">{e(l["role"])} · {e(l["country"])}</span><h2>{e(l["name"])}</h2><p>{e(l["address"])}</p><a href="tel:+{l["phone"]}">{icon("phone")} {e(l["phoneDisplay"])}</a><a href="mailto:{l["email"]}">{icon("mail")} {e(l["email"])}</a>{phones}<p class="form-note">{note}</p><div class="location-actions"><a class="text-link" target="_blank" rel="noopener noreferrer" href="{e(directions)}">Address on map ↗</a><a class="text-link" href="contact.html?location={l["id"]}">Enquire here →</a></div></article>')
 legacy=c['legacyLocations'][0]
 shell('locations.html','Locations & experience centres',pagehead('Locations','Closer to your care.','Published manufacturing, office and experience-centre contacts in India and the UAE.')+f'<div class="section"><div class="company-contact-strip"><a href="tel:18008917466">Toll-free: 1800 891 7466</a><a href="tel:+919289976683">General enquiries: +91 9289976683</a><a href="mailto:info@drsmith.co.in">info@drsmith.co.in</a></div><div class="locations-grid">{"".join(locationcards)}</div><div class="legacy-location"><h2>Additional service-centre reference</h2><p>{e(legacy["name"])} · {e(legacy["address"])} The source location data includes this legacy reference, but its current status and full street address are unconfirmed. Contact central support before making arrangements.</p><a href="tel:+{legacy["phone"]}">{e(legacy["phoneDisplay"])}</a></div></div>')
 options=''.join(f'<option value="{e(l["name"])}" data-location-id="{l["id"]}">{e(l.get("displayName",l["role"]+" – "+l["name"]))}</option>' for l in c['locations'])
 form=f'''<form id="contact-form" class="form-card"><h2>Prepare a support request</h2><div class="form-row"><label>Your name<input name="name" autocomplete="name" required maxlength="100"></label><label>Organisation<input name="organisation" autocomplete="organization" maxlength="160"></label></div><div class="form-row"><label>Email<input name="email" type="email" autocomplete="email" required maxlength="160"></label><label>Phone / WhatsApp<input name="phone" type="tel" autocomplete="tel" required maxlength="22"></label></div><label>Support required<select name="supportType" required><option value="">Select support type</option>{''.join(f'<option>{s}</option>' for s in ['Installation & setup','Product operation & training','Technical issue','Warranty assistance','Maintenance / service','Spare parts / accessories'])}</select></label><div class="form-row"><label>Product / model<input name="product" required maxlength="160"></label><label>Serial or order reference<input name="reference" required maxlength="160"></label></div><label>Nearest location<select name="location" required><option value="">Choose your location</option>{options}</select></label><label>Equipment / site address<input name="siteAddress" required maxlength="300"></label><label>Issue or support details<textarea id="contact-message" name="message" rows="5" required maxlength="3000"></textarea></label><label>Preferred contact method<select name="contactMethod"><option>Phone call</option><option>WhatsApp</option><option>Email</option></select></label><p class="form-note">Prepare and review your request, then choose email or WhatsApp to send it. Support scope, eligibility and response arrangements are confirmed by the team.</p><button class="button" type="submit">Review support request →</button><div id="contact-review"></div></form>'''
 shell('support.html','Service & support',pagehead('Support','Support beyond the product.','Installation, training, technical queries, warranty, maintenance and spare parts.')+'<div class="section contact-layout"><div class="contact-details"><span class="eyebrow">AFTER YOUR PURCHASE</span><h2>Help us understand your equipment.</h2><p>Share the product model, serial or order reference, purchase details and a description of the issue. The team will review your request and explain the next step.</p><p>Installation, training and service depend on the product, location and agreed scope. A 24/7 contact channel does not guarantee immediate on-site attendance or a resolution time.</p><a href="tel:+919289976683">+91 9289976683</a><a href="mailto:info@drsmith.co.in">info@drsmith.co.in</a><a class="text-link" href="warranty.html">Warranty information →</a></div>'+form+'</div>')
 meeting=f'''<form id="contact-form" class="form-card"><h2>Prepare a meeting request</h2><div class="form-row"><label>Your name<input name="name" required autocomplete="name" maxlength="100"></label><label>Organisation / individual<input name="organisation" required maxlength="160"></label></div><div class="form-row"><label>Email<input name="email" required type="email" autocomplete="email" maxlength="160"></label><label>Phone<input name="phone" type="tel" required autocomplete="tel" maxlength="22"></label></div><label>Meeting format<select name="meetingFormat"><option>Phone call</option><option>Video meeting</option><option>In-person visit</option></select></label><div class="form-row"><label>Preferred date<input name="meetingDate" type="date" required></label><label>Preferred time window<input name="meetingTime" required placeholder="For example, 10 am–12 pm" maxlength="80"></label></div><label>Your time zone<input name="timezone" required value="Asia/Kolkata" maxlength="80"></label><label>Location<select name="location"><option value="">Select for an in-person visit</option>{options}</select></label><label>Reason for meeting<textarea name="message" id="contact-message" required rows="5" maxlength="3000"></textarea></label><p class="form-note">This prepares a request, not a confirmed booking. Our team must accept the time and share meeting details.</p><button class="button">Review meeting request →</button><div id="contact-review"></div></form>'''
 shell('meeting.html','Request a meeting',pagehead('Meeting request','A meeting. A clearer next step.','Discuss your products or project with the team by phone, video or an arranged visit.')+'<div class="section meeting-form">'+meeting+'</div>')
 policy('warranty.html','Warranty & service information',[
 ('Eligible-product replacement cover','One-year replacement cover is available only on eligible products under the model-specific warranty and written quotation. Confirm eligibility, period, exclusions, claim requirements and the responsible supplying entity before ordering.'),
 ('Installation, training and support','Available services depend on your product, location and agreed scope. Confirm included services, charges, lead times and any partner arrangements. A 24/7 support channel does not imply an immediate on-site visit or guaranteed resolution time.'),
 ('Requesting support','Provide your product model, order reference, purchase date and issue description. Do not include passwords or patient information. <a href="support.html">Prepare a support request →</a>'),
 ('Written terms','Your quotation, invoice and warranty documentation identify the commercial scope. These notes do not limit rights that cannot be excluded by applicable law. <a href="terms.html">Sales enquiry information →</a>')])
 policy('terms.html','Website terms & sales enquiries',[
 ('Company roles','Dr. Smith is the product brand. Surgical Wholesale Mart Pvt. Ltd. is a separate procurement, experience-centre and project-coordination collaborator. The supplier, service provider and responsibilities must be identified in your written quotation or contract.'),
 ('Product information & orders','Confirm model, specification, origin, applicable certifications, quantity, price, taxes, availability, delivery and installation scope before ordering. Not every item is manufactured in-house. Images help identify a range; request current technical documentation for the quoted configuration.'),
 ('Enquiries & quotations','Preparing or sharing an enquiry does not place an order, reserve stock or confirm delivery. Orders and requested dates are subject to written acceptance and agreed commercial terms.'),
 ('Projects & visits','Project feasibility, scope, partner-supported services, installation and handover responsibilities are agreed individually. Confirm an experience-centre address, operational status and demonstration availability before travelling.'),
 ('Warranty, returns & cancellation','Replacement cover applies to eligible products under agreed terms. Confirm warranty, service, replacements, returns and cancellation conditions for each product and order. <a href="warranty.html">Read warranty information →</a>'),
 ('Contact','Email <a href="mailto:info@drsmith.co.in">info@drsmith.co.in</a>, call <a href="tel:18008917466">1800 891 7466</a> or <a href="tel:+919289976683">+91 9289976683</a> for the applicable supplying entity and sales terms.')])
 policy('privacy.html','Privacy & your enquiries',[
 ('Information you choose to share','Enquiry forms collect the contact, organisation, product, delivery or support information you enter. This storefront prepares a draft locally; it does not automatically submit the draft to an enquiry server.'),
 ('Browser storage','Your quote basket and saved product IDs are stored in local storage. The quotation contact draft is stored in session storage for the review step and can be discarded on that screen. Closing the browsing session normally clears session data. Contact, support and meeting form reviews are held in the page until you leave or reload.'),
 ('Email, WhatsApp & downloads','You choose whether to open an email draft, open WhatsApp or download a text copy. Details are passed to the application you select. You review and send the message there. The selected service and receiving team handle the sent enquiry under their own terms.'),
 ('External services','Map, social, catalogue and source-company links open external sites. Web fonts may load from Google Fonts. Hosting providers may retain ordinary technical and security logs. Avoid entering patient records, passwords, payment card information or other sensitive material in enquiries.'),
 ('Information requests','Contact <a href="mailto:info@drsmith.co.in">info@drsmith.co.in</a> or <a href="tel:+919289976683">+91 9289976683</a> about correction or removal of enquiries held by the receiving team. Records required for quotation, fulfilment, security or legal obligations may need to be retained.')])
 # Enrich the existing contact and checkout pages without replacing their forms.
 p=root/'contact.html';html=p.read_text();insert=f'''<div class="section company-contact-strip"><a href="tel:+919289976683">General enquiries: +91 9289976683</a><a target="_blank" rel="noopener noreferrer" href="https://wa.me/919289976683">WhatsApp the team ↗</a><a href="locations.html">All offices & experience centres →</a><a href="support.html">Service & support →</a><a href="meeting.html">Request a meeting →</a></div>''';html=html.replace('</main>',insert+'</main>');html=html.replace('<label>What do you need?',f'<label>Contact location<select name="location" id="contact-location"><option value="">Choose a location</option>{options}</select></label><label>What do you need?');p.write_text(html)
 p=root/'checkout.html';html=p.read_text().replace('<label>Requirements &amp; preferred configuration','<label>Requirements &amp; preferred configuration')
 html=html.replace('<label>Requirements & preferred configuration',f'<label>Contact location<select name="location"><option value="">Choose a location</option>{options}</select></label><label>Requirements & preferred configuration');p.write_text(html)
 # Add source details and public links to services.
 p=root/'services.html';html=p.read_text().replace('</main>','<div class="section company-document">'+projects+reach+'</div></main>');p.write_text(html)
 print('Added company profile, 10 current locations, legacy reference, support, meeting, warranty, privacy and sales information.')
